package jp.amaro.survival.bootstrap;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.net.URI;import java.net.http.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class LauncherShutdownServerTest{@TempDir Path temp;@Test void tokenWorksOnceAndArbitraryPathIsRejected()throws Exception{AtomicInteger calls=new AtomicInteger();Path handoff=temp.resolve("token");try(LauncherShutdownServer server=new LauncherShutdownServer(handoff,calls::incrementAndGet)){server.start();String token=Files.readString(handoff).trim();HttpClient client=HttpClient.newHttpClient();assertEquals(401,post(client,"/launcher/shutdown","invalid").statusCode());assertEquals(401,post(client,"/launcher/shutdown/command",token).statusCode());assertEquals(202,post(client,"/launcher/shutdown",token).statusCode());assertEquals(1,calls.get());assertFalse(Files.exists(handoff));assertEquals(401,post(client,"/launcher/shutdown",token).statusCode());}}private static HttpResponse<String> post(HttpClient c,String path,String token)throws Exception{return c.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+LauncherShutdownServer.PORT+path)).header("X-ASBP-Shutdown-Token",token).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());}}
